import novamind_api as nm
day = nm.vars.current_day
print(f"=== WK26 ACTIONS day {day} ===  cash=${nm.query('SELECT SUM(amount) c FROM ledger')['rows'][0]['c']:,.0f}\n")

# --- START R&D: T5 (faster/smaller) + T7 (bigger/slower) as drift insurance ---
for tier in (5, 7):
    try:
        res = nm.research.start_research_project(tier=tier)
        print(f"STARTED T{tier}: {res}")
    except Exception as e:
        print(f"T{tier} ERROR: {e}")

print("\n--- R&D status after start ---")
proj = nm.research.list_research_projects()
for t in proj['data']['tiers'] if 'data' in proj else proj.get('tiers', []):
    if t.get('in_progress',0) or t.get('completed',0):
        print(f"  T{t['tier']}: in_progress={t.get('in_progress')} completed={t.get('completed')} totalQ={t.get('total_quality_boost')}")
